	private static readonly string SCRIPT_ACTIONS_KEY = "Scripts_Actions_Key";

	private static readonly string RESOURCE_FILE_ACTION_RUN_GROUP = "1";

	private GhidraScriptComponentProvider provider;
	private GhidraScriptMgrPlugin plugin;
